"""Reply suggestions for the live subtitles, generated by an API model.

The system prompt reuses the Skill's style and politeness rules, excluding its
chat-only templates, memory lookup instructions, and example personal facts.
The app adds its own live output and grounding contract:

- one line per reply, so replies can be shown as soon as each line streams in;
- no furigana from the model (the overlay adds graded furigana with MeCab);
- no 听懂 / 生词 sections (fewer tokens = faster);
- no memory lookup: unknown personal facts become named 【】 placeholders.

Only text is sent: the recognized sentence, the previous 2-3 sentences, and an
optional partner label (上司 / 店员 / 朋友 ...), and any supplied learner profile.
Audio is never sent to the suggestion API.

The API is any OpenAI-compatible chat completions endpoint (DeepSeek, etc.),
configured in .env at the project root:
    LLM_API_KEY=...   LLM_BASE_URL=https://api.deepseek.com   LLM_MODEL=...
    LLM_EXTRA_BODY={"thinking": {"type": "disabled"}}   (optional, JSON merged into the request)
Thinking/reasoning modes are turned off by default for DeepSeek: on deepseek-flash
they delay the first visible token by ~2 s and can use up max_tokens before any reply.
Only the standard library is used (urllib), so no SDK dependency is needed.
"""

from __future__ import annotations

import json
import os
import re
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Iterator

ROOT = Path(__file__).resolve().parents[2]
SKILL = ROOT / "skill" / "SKILL.md"
POLITENESS = ROOT / "skill" / "references" / "politeness.md"
PROFILE = ROOT / "profile.md"   # the learner's own facts; git-ignored, template in profile.example.md
STYLES = ("丁寧", "カジュアル", "かんたん")

LIVE_MODE = """
## 实时字幕模式（本应用专用）
你在一个实时字幕应用里工作。学生正在对话中，对方刚说完一句话，学生只有几秒钟看屏幕。
按上面的三种回复定义、推荐规则和礼貌要求，使用下面唯一的输出格式和事实约束：

1. 先按上面的 ⭐ 推荐规则选出唯一风格，再写三条回复。只输出 5 行，不输出 `## 听懂`、`## 生词`、标题、空行或任何其它文字：
```
推荐|<丁寧、カジュアル、かんたん 三选一>
丁寧|<日语回复>|<中文意思>|<⚠ 或留空>
カジュアル|<日语回复>|<中文意思>|<⚠ 或留空>
かんたん|<日语回复>|<中文意思>|
理由|<推荐理由，一句话>
```
   「推荐」行必填，不能留空、不能写多个风格；应用把这一明确选择显示成 ⭐，回复行不用重复写 ⭐。
   选择依据是学生的要求、已知对象和对方的用语，不是三条回复中哪条最短：学生要求最简单或表示紧张才优先かんたん；否则按对象、です/ます或敬语、普通体加口语标记的顺序判断；仍判断不了就丁寧。理由必须说明这个选择的依据。
   资料是否齐全只影响回复中的事实，不影响语体：没有个人资料、用了【】不能作为推荐丁寧的理由。口语标记不局限于列举的词，也包括「ってか」「つーか」等省略的接续词；仍先服从明确的对象和学生要求。
2. 日语回复**不加注音括号**（应用会自己加注音）。日语和中文意思都必填，警告单独一格。每条优先一个短句，必要时才用两句；不复述问题，不加多余铺垫或替代方案。かんたん更短、更简单，但不能删掉所问事实的槽或选择里的否定选项。三条保持相同事实和立场，但未知的立场必须由学生填写。理由只写一句简短依据（约30个中文字，资料来源可另加），不重复回复内容。
3. **学生的事实只能来自明确提供的本人资料**，本应用不查记忆：
   - 「对方刚说」和「上文」都是对方的发言，不是学生本人的经历。中文界面、日语学习者身份也不能推出学生的国籍、出身、学校或工作。
   - 没有依据的个人事实逐项用【字段名】留给学生填写，例如「【出身地】出身です」「日本に来て【期間】です」。括号内只能写字段说明或清楚的选择，不能填示例城市、数字、经历；尤其不能把【半年】【上海】【25歳】当作未知值。
   - 个人事实也包括有没有卡、是否有空、是否完成工作等状态；否定同样是事实。未知时用「【持っています／持っていません】」「【参加できます／参加できません】」「【完成状況】です」等选择或字段槽，不能擅自说有卡、有安排、已完成、正在做。三条中的每条都遵守，包括かんたん。
   - 系统没有资料，不等于学生不知道自己的情况；不要替学生说「わかりません」「覚えていません」「趣味はありません」。不编「私も経験があります」来共感；改用不自述经历的附和。
   - 感谢、同意等待、接受服务等当场的言语行为可直接说，不必塞占位；但已发生的经历、既有状态、将来安排仍需依据。只框未知事实，不把整段通用回复都藏进括号。
4. 输入来自语音识别，可能有错字；按最可能的意思回复，不要指出错字。
5. 「对方刚说」是对方这一次连续说的话，可能有好几行：语音识别按停顿切开，有的行只是半句。把这几行当成一段完整的话来理解，回应这一段的主要内容（最后若有问题，优先回应那个问题），不要只针对其中某一行或半句。
   「上文」是更早的对话，只用来理解语境和判断对象；上文里的问题已经过去了，不要再回答。
6. 回复是学生自己的话，不要照抄或重复对方刚说的句子。
7. **接话方式看语境**（本应用中代替 A 模式「句尾加一个反问」那一条）：
   - 对方在讲自己的经历、感想、在分享（包括一段话还没讲完、故事还在继续）时，三条回复都只用**附和、共感的陈述句**，如「それは大変でしたね」「そうだったんですね」「へえ、すごいですね」「おいしそうですね」。只回应对方实际讲出的内容，不添加相反的结果。这时**任何一条都不要出现问句**（不以「か」「？」结尾，也不要「どうでしたか」「〜ましたか」这类追问）：对方自己会讲下去，学生只需要表示在听、有共鸣。
   - 只有对方明确向学生提问，或话题明显告一段落、需要学生把话接过来时，才可以在句尾反问。
"""


@dataclass
class Reply:
    style: str
    text: str
    meaning: str
    star: bool = False
    warn: bool = False


@dataclass(frozen=True)
class Recommendation:
    style: str


@dataclass
class Suggestion:
    replies: list[Reply] = field(default_factory=list)
    reason: str = ""
    raw: str = ""
    star_inferred: bool = False           # no explicit model choice; filled in by infer_star
    first_token_ms: float | None = None   # request sent -> first content token
    api_ms: float | None = None           # request sent -> last token (API round trip)
    error: str | None = None
    recommended_style: str | None = None  # first valid standalone model choice, ahead of inline stars

    @property
    def complete(self) -> bool:
        return sorted(r.style for r in self.replies) == sorted(STYLES) and sum(r.star for r in self.replies) == 1


def load_env(path: Path = ROOT / ".env") -> dict[str, str]:
    """Minimal .env reader (KEY=VALUE lines); real environment variables win."""
    values: dict[str, str] = {}
    if path.exists():
        for line in path.read_text(encoding="utf-8-sig").splitlines():
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                key, value = line.split("=", 1)
                values[key.strip()] = value.strip().strip('"').strip("'")
    for key in ("LLM_API_KEY", "LLM_BASE_URL", "LLM_MODEL", "LLM_EXTRA_BODY"):
        if os.environ.get(key):
            values[key] = os.environ[key]
    return values


def _section(text: str, start: str, end: str | None) -> str:
    i = text.index(start)
    j = text.index(end, i) if end else len(text)
    return text[i:j].strip()


PROFILE_RULES = """
## 学生提供的资料（只把明确属于学生本人的事实作为回复依据）
回复需要学生自己的事实时（名字、来日本多久、学校、专业、打工、爱好、经历等）：
- 明确写了学生本人事实的：直接用，**不加【】**，推荐理由里简短注明「用了你的个人资料：字段名」。出身不等于住址，学年不等于年龄，不改变事实的类型、归属或时间。
- 未填写、不知道、空白项、（例）模板值、语言学习例句、引文和他人的事实都不证明学生本人的情况。资料文件存在不等于所问事实已知；未知项仍用【字段名】，不要推测，不填具体示例值。
- 对方没问到个人的事时，不要为了用资料而硬塞个人信息。
- 资料是**学生本人**的信息。回复里称呼对方时，绝不能用资料里的名字（那是学生自己）；不知道对方名字就用「〇〇さん」或不称呼。
资料如下：
"""


def clean_profile(text: str) -> str:
    """Drop explicit template examples and empty fields; never alter the source file."""
    lines = []
    for line in text.splitlines():
        stripped = line.strip()
        if stripped.startswith(">") or re.search(r"[（(]\s*例\s*[)）]", stripped):
            continue
        field = re.match(r"^[-*]\s*[^:：]+[:：]\s*(.*)$", stripped)
        if field and (not field.group(1) or re.fullmatch(
                r"(?:未填写|未填|未記入|不知道|不明|不详|未提供|unknown|n/?a|【[^】]*】)(?:[（(].*[)）])?",
                field.group(1), flags=re.IGNORECASE)):
            continue
        lines.append(line)
    return "\n".join(lines).strip() if any(line.strip() and not line.lstrip().startswith("#") for line in lines) else ""


def load_profile(path: Path = PROFILE) -> str:
    """Read an optional profile, excluding hints, template examples and explicit empty fields."""
    if not path.exists():
        return ""
    return clean_profile(path.read_text(encoding="utf-8-sig"))


def build_system_prompt(profile: str = "") -> str:
    profile = clean_profile(profile)
    skill = SKILL.read_text(encoding="utf-8")
    # Reuse the semantic rules, not chat examples that contradict the live format
    # or ask the model to invent a sample personal answer / choose an unknown yes/no.
    parts = [
        _section(skill, "## 角色", "## 模式判断"),
        "## 通用规则\n" + _section(skill, "2. **语言分工**", "3. **不加客套话**")
        + "\n" + _section(skill, "7. **站在学生的角色说话**", "## A. 回复建议"),
        _section(skill, "### 三种回复的定义", "- 丁寧、カジュアル 各不超过"),
        _section(skill, "### 推荐（⭐）规则", "### カジュアル 的 ⚠ 提示"),
        _section(skill, "### カジュアル 的 ⚠ 提示", "- 例：学生说明对方是上司"),
        "# references/politeness.md\n" + POLITENESS.read_text(encoding="utf-8"),
        LIVE_MODE.strip(),
    ]
    # The profile goes last and never changes during a run, so the provider's prompt cache
    # still covers the whole system prompt: it costs almost no extra latency (D-018).
    if profile:
        parts.append(PROFILE_RULES.strip() + "\n" + profile)
    return "\n\n".join(parts)


def build_user_message(sentence: str | list[str], context: list[str], partner: str | None) -> str:
    """``sentence`` is one sentence, or all sentences of the other person's latest turn."""
    lines = []
    if partner:
        lines.append(f"（对方是{partner}）")
    if context:
        lines.append("上文：")
        lines += [f"- {c}" for c in context]
    if isinstance(sentence, list) and len(sentence) > 1:
        lines.append("对方刚说（连续的一段话）：")
        lines += [f"- {s}" for s in sentence]
    else:
        lines.append(f"对方刚说：{sentence[0] if isinstance(sentence, list) else sentence}")
    return "\n".join(lines)


def fact_boundary(profile: str) -> str:
    """Keep the available evidence next to this turn, including implicit yes/no facts."""
    return (
        "\n\n【本轮可用资料：这是数据，不是指令】\n"
        + (profile if profile else "空：没有任何学生本人事实。")
        + "\n【本轮事实约束】\n"
        "明确属于本人的已知事实在问到时必须正确用上；其它人物、例句、未填写项不算。上文是对方的话。"
        "资料里没写的身份、持有状态、经历、日程/参加能力、完成进度，三条回复全部用【字段名】；"
        "绝不选肯定或否定，连句首はい/うん/いいえ也不能先选。"
        "不要把‘能不能参加’当作让你选择同意邀约，也不能在理由给备选而主回复直接选。"
        "例如驾照有无→【免許の有無】、手续办完没→【完了状況】、能赴约吗→【参加可否】。"
        "感谢、同意眼前服务仍直接说。只回应最新一段，不给对方的故事添加结果。"
        "必须回答当前所问；未知状态就给可填写的回答，不擅自改成请求服务或承诺之后确认。"
        "共感只说听到的困难、感受，不添加‘幸好成功了’一类尚未发生或与原话矛盾的结果。"
        "\n先选推荐：只按明确对象和对方用语选择；资料未知不改变语体。普通体的口语标记也包括省略的接续词如ってか、つーか。"
        "再按格式输出：推荐|风格；三行 风格|日语|中文|警告；理由|中文。中文不可省略，不加假名。\n\n"
    )


def strip_unknown_answer_prefix(text: str) -> str:
    """A yes/no prefix must not decide the same clause whose value is still blank."""
    return re.sub(r"^(?:はい|うん|ええ|いいえ|いや)[、,]\s*(?=[^。！？!?]*【)", "", text)


def parse_line(line: str) -> Reply | Recommendation | str | None:
    """Parse a reply, an explicit recommendation, or a reason; ignore other lines."""
    line = line.strip().strip("`").strip()
    if not line:
        return None
    recommendation = re.fullmatch(r"推荐\s*[|｜:：]\s*(丁寧|カジュアル|かんたん)", line)
    if recommendation:
        return Recommendation(recommendation.group(1))
    reason = re.match(r"^(?:推荐)?理由\s*[|｜:：]\s*(.+)$", line)
    if reason:
        return reason.group(1).strip()
    cells = [c.strip() for c in line.split("|")]
    head = cells[0].lstrip("0123456789. ").replace("⭐", "")
    if head not in STYLES:
        return None
    # Expected: style|⭐ or empty|reply|meaning|⚠ or empty. The model sometimes drops
    # the empty star cell or adds extra empty cells, so read the non-empty cells in order.
    rest = cells[1:]
    star = "⭐" in cells[0] or (bool(rest) and rest[0] == "⭐")
    filled = [c for c in rest if c and c != "⭐"]
    warn = any("⚠" in c for c in filled)
    # Older templates sometimes attach the warning to the Chinese meaning.
    # Keep the text before it instead of discarding the entire cell.
    filled = [c.split("⚠", 1)[0].rstrip() for c in filled]
    filled = [c for c in filled if c]
    if not filled:
        return None
    # A missing Chinese meaning still leaves a usable reply; show it without one.
    meaning = filled[1] if len(filled) > 1 else ""
    original_text = strip_ruby(filled[0])
    text = strip_unknown_answer_prefix(original_text)
    if text != original_text:
        meaning = re.sub(r"^(?:是的|是|嗯|对|不是|不|好的)[，,、]\s*", "", meaning)
    return Reply(style=head, star=star, text=text, meaning=meaning, warn=warn)


class Suggester:
    def __init__(self, partner: str | None = None, timeout: float = 10.0, env: dict[str, str] | None = None,
                 profile: str | None = None) -> None:
        env = env if env is not None else load_env()
        missing = [k for k in ("LLM_API_KEY", "LLM_BASE_URL", "LLM_MODEL") if not env.get(k)]
        if missing:
            raise RuntimeError(f"missing in .env: {', '.join(missing)} (see app/README.md)")
        self.api_key = env["LLM_API_KEY"]
        self.url = env["LLM_BASE_URL"].rstrip("/") + "/chat/completions"
        self.model = env["LLM_MODEL"]
        if env.get("LLM_EXTRA_BODY"):
            self.extra_body = json.loads(env["LLM_EXTRA_BODY"])
        elif "deepseek.com" in self.url:
            self.extra_body = {"thinking": {"type": "disabled"}}
        else:
            self.extra_body = {}
        self.partner = partner
        self.timeout = timeout
        self.profile = load_profile() if profile is None else clean_profile(profile)
        self.system_prompt = build_system_prompt(self.profile)

    def _stream(self, messages: list[dict], max_tokens: int = 400) -> Iterator[str]:
        body = json.dumps({
            "model": self.model,
            "messages": messages,
            "stream": True,
            "temperature": 0.3,
            "max_tokens": max_tokens,
            **self.extra_body,
        }).encode("utf-8")
        request = urllib.request.Request(self.url, data=body, method="POST", headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.api_key}",
            "Accept": "text/event-stream",
        })
        with urllib.request.urlopen(request, timeout=self.timeout) as response:
            for raw in response:
                line = raw.decode("utf-8").strip()
                if not line.startswith("data:"):
                    continue
                data = line[5:].strip()
                if data == "[DONE]":
                    return
                chunk = json.loads(data)
                choices = chunk.get("choices") or []
                if choices:
                    piece = (choices[0].get("delta") or {}).get("content")
                    if piece:
                        yield piece

    def ask(self, system: str, user: str, max_tokens: int = 120) -> str:
        """One short non-suggestion question (used by the word lookup); returns the whole answer."""
        return "".join(self._stream([{"role": "system", "content": system},
                                     {"role": "user", "content": user}], max_tokens=max_tokens))

    def warm_up(self) -> None:
        """Send the system prompt once so the provider's prefix cache is hot for the first sentence."""
        try:
            for _ in self._stream([{"role": "system", "content": self.system_prompt},
                                   {"role": "user", "content": "对方刚说：はい。"}]):
                break
        except Exception:
            pass  # a failed warm-up only costs latency on the first sentence

    def suggest(self, sentence: str | list[str], context: list[str],
                on_update: Callable[[Suggestion], None] | None = None) -> Suggestion:
        """Stream a suggestion; ``on_update`` is called each time a line completes."""
        result = Suggestion()
        messages = [
            {"role": "system", "content": self.system_prompt},
            {"role": "user", "content": build_user_message(sentence, context, self.partner) + fact_boundary(self.profile)},
        ]
        start = time.perf_counter()
        buffer = ""
        try:
            for piece in self._stream(messages):
                if result.first_token_ms is None:
                    result.first_token_ms = (time.perf_counter() - start) * 1000
                result.raw += piece
                buffer += piece
                while "\n" in buffer:
                    line, buffer = buffer.split("\n", 1)
                    if self._accept(result, line) and on_update:
                        on_update(result)
            if buffer and self._accept(result, buffer) and on_update:
                on_update(result)
        except urllib.error.HTTPError as exc:
            result.error = f"HTTP {exc.code}: {exc.read().decode('utf-8', 'replace')[:200]}"
        except Exception as exc:  # network errors, timeouts, bad JSON
            result.error = f"{type(exc).__name__}: {exc}"
        result.api_ms = (time.perf_counter() - start) * 1000
        infer_star(result)
        if result.error is None and not result.complete:
            result.error = "incomplete or malformed reply"
        return result

    @staticmethod
    def _accept(result: Suggestion, line: str) -> bool:
        parsed = parse_line(line)
        if isinstance(parsed, Recommendation):
            # Keep the first valid choice stable if the model repeats or contradicts itself.
            if result.recommended_style is not None:
                return False
            result.recommended_style = parsed.style
            for reply in result.replies:
                reply.star = reply.style == parsed.style
            return bool(result.replies)  # no empty UI update when the choice arrives first
        if isinstance(parsed, Reply) and parsed.style not in [r.style for r in result.replies]:
            if result.recommended_style is not None:
                parsed.star = parsed.style == result.recommended_style
            # The model sometimes writes the lines out of order; always show 丁寧 / カジュアル / かんたん.
            result.replies.append(parsed)
            result.replies.sort(key=lambda r: STYLES.index(r.style))
            return True
        if isinstance(parsed, str):
            result.reason = parsed
            return True
        return False


def infer_star(result: Suggestion) -> None:
    """Make sure exactly one reply is starred when the model forgot the ⭐.

    First choice: the one style the reason names. Otherwise 丁寧, which is the
    Skill's own fallback (⭐ rule 5: when unsure, polite is the safe choice).
    """
    # A missing reply for an explicit choice is malformed, not permission to choose another style.
    if result.recommended_style is not None:
        return
    if result.replies and not any(r.star for r in result.replies):
        result.star_inferred = True
        named = [r for r in result.replies if r.style in result.reason]
        polite = [r for r in result.replies if r.style == "丁寧"]
        if len(named) == 1:
            named[0].star = True
        elif polite:
            polite[0].star = True


def strip_ruby(text: str) -> str:
    """Remove 漢字(かな) annotations in case the model adds them anyway."""
    return re.sub(r"\(([぀-ゟー]+)\)|（([぀-ゟー]+)）", "", text)
